81	/**
82	 * It's a symbol demangler that can be used as a replacement for the GNU c++filt tool. 
83	 * It takes a series of symbol names and prints their demangled form on the standard output stream. 
84	 * If a name cannot be demangled, it is simply printed as is.
85	 * 
86	 * example: 
87	 * _ZN10__cxxabiv120__unexpected_handlerE   ->   __cxxabiv1::__unexpected_handler
88	*/
89	export function cxxDemangle(name: string, cxxfilt_path?: string): string {
90	    cxxfilt_path = cxxfilt_path || `arm-none-eabi-c++filt${platform.exeSuffix()}`;
91	    try {
92	        return child_process.execFileSync(cxxfilt_path, [name]).toString().trim();
93	    } catch (error) {
94	        return name;
95	    }
96	}
