138	    protected parseMacroString(macroStr: string): string[] {
139	
140	        if (typeof macroStr !== 'string')
141	            return [];
142	
143	        const result: string[] = [];
144	        const charStack: string[] = [];
145	
146	        const pushToResult = (str: string) => {
147	            const macro = str.trim();
148	            if (macro && /^[_a-z].*/i.test(macro)) {
149	                result.push(macro);
150	            }
151	        };
152	
153	        let curSubStr: string = '';
154	        for (let index = 0; index < macroStr.length; index++) {
155	
156	            let prevChar = index > 0 ? macroStr[index - 1] : '';
157	            let curChar = macroStr[index];
158	            let nxtSubStr = macroStr.substr(index + 1);
159	
160	            // 处理宏定义中的字符串
161	            if (curChar === '"' || curChar === '\'') {
162	                if (prevChar !== '\\') { // ignore '\"' in string
163	                    if (charStack.length > 0) {
164	                        if (charStack[charStack.length - 1] === curChar) {
165	                            charStack.pop();
166	                            // force make ' => "
167	                            if (curChar === '\'') { curChar = '"'; }
168	                        }
169	                    }
170	                    else {
171	                        charStack.push(curChar);
172	                        // force make ' => "
173	                        if (curChar === '\'') { curChar = '"'; }
174	                    }
175	                }
176	            }
177	            // 分割宏定义
178	            else if (curChar === ' ' || curChar === ',') {
179	                if (charStack.length === 0) {
180	                    // 剔除 ‘=’ 两边的空格
181	                    if (curChar === ' ' && nxtSubStr.trimStart().startsWith('='))
182	                        continue;
183	                    if (curChar === ' ' && curSubStr.endsWith('='))
184	                        continue;
185	                    pushToResult(curSubStr);
186	                    curSubStr = ''; // reset it
187	                    continue; // skip split char
188	                }
189	            }
190	
191	            curSubStr += curChar;
192	        }
193	
194	        // push remaining str
195	        pushToResult(curSubStr);
196	
197	        return result;
198	    }
