getIncludeDirs(): string[] {
    const incList = this.project.GetConfiguration()
        .GetAllMergeDep([`${ProjectConfiguration.BUILD_IN_GROUP_NAME}.${DependenceManager.toolchainDepName}`])
        .incList;
    return ArrayDelRepetition(incList.concat(
